// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('RobotoMono');

const { fontFamily } = loadFont();



export type ThermometerProps = Record<string, any>;

// Helper to construct the unified path for the thermometer outline
const buildThermoPath = (
  cx: number,
  cy: number,
  bulbR: number,
  tubeTopY: number,
  tubeR: number
) => {
  const intersectOffset = Math.sqrt(
    Math.max(0, bulbR * bulbR - tubeR * tubeR)
  );
  const intersectY = cy - intersectOffset;

  return `
    M ${cx - tubeR} ${tubeTopY + tubeR}
    A ${tubeR} ${tubeR} 0 0 1 ${cx + tubeR} ${tubeTopY + tubeR}
    L ${cx + tubeR} ${intersectY}
    A ${bulbR} ${bulbR} 0 1 1 ${cx - tubeR} ${intersectY}
    Z
  `;
};

const Thermometer: React.FC<ThermometerProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,
  startValue = 1,
  endValue = 100,
  glassColor = "#94a3b8",
  liquidColor = "#ef4444",
  textColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timings
  const durationFrames = durationInSeconds * fps;
  const fillStart = Math.min(fps, durationFrames * 0.2); // Start filling after 1s or 20%
  const fillEnd = Math.max(fillStart + 1, durationFrames * 0.85); // Finish filling slightly before end

  // Intro Animation
  const introSpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
    durationInFrames: 30,
  });

  // Value Interpolation
  const progress = interpolate(frame, [fillStart, fillEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.25, 1, 0.5, 1),
  });

  const currentValue = interpolate(
    progress,
    [0, 1],
    [startValue, endValue]
  );
  const displayValue = Math.round(currentValue);

  // Geometry calculations
  const cx = width * 0.38;
  const bulbCy = height * 0.7;
  const bulbRadius = height * 0.12;
  const tubeWidth = height * 0.08;
  const tubeTopY = height * 0.2;
  const tubeRx = tubeWidth / 2;
  const thick = height * 0.012;

  // Outer Path
  const outerPath = buildThermoPath(cx, bulbCy, bulbRadius, tubeTopY, tubeRx);

  // Inner Path (used for hollow mask and liquid clipping)
  const innerBulbRadius = bulbRadius - thick;
  const innerTubeRx = tubeRx - thick;
  const innerTubeTopY = tubeTopY + thick;
  const innerPath = buildThermoPath(
    cx,
    bulbCy,
    innerBulbRadius,
    innerTubeTopY,
    innerTubeRx
  );

  // Intersections for details
  const intersectOffsetOuter = Math.sqrt(
    Math.max(0, bulbRadius * bulbRadius - tubeRx * tubeRx)
  );
  const intersectYOuter = bulbCy - intersectOffsetOuter;

  const intersectOffsetInner = Math.sqrt(
    Math.max(0, innerBulbRadius * innerBulbRadius - innerTubeRx * innerTubeRx)
  );
  const innerIntersectY = bulbCy - intersectOffsetInner;

  // Liquid limits
  const liquidEmptyY = bulbCy + innerBulbRadius - height * 0.01; // tiny sliver visible at 0
  const liquidFullY = innerTubeTopY + innerTubeRx;
  const currentLiquidY = interpolate(
    progress,
    [0, 1],
    [liquidEmptyY, liquidFullY]
  );

  // Tick Marks
  const numMarks = 10;
  const marks = Array.from({ length: numMarks + 1 }).map((_, i) => {
    const yPos =
      innerTubeTopY +
      innerTubeRx +
      (i / numMarks) * (innerIntersectY - (innerTubeTopY + innerTubeRx));
    return (
      <line
        key={i}
        x1={cx + tubeRx + height * 0.01}
        x2={cx + tubeRx + height * 0.035}
        y1={yPos}
        y2={yPos}
        stroke={glassColor}
        strokeWidth={height * 0.005}
        strokeLinecap="round"
      />
    );
  });

  const textLeft = cx + tubeRx + height * 0.1;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          transform: `scale(${introSpring})`,
          opacity: introSpring,
          transformOrigin: "center center",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* SVG Graphic */}
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", left: 0, top: 0, overflow: "visible" }}
        >
          <defs>
            {/* Hollow out the glass */}
            <mask id="hollow-mask">
              <rect width={width} height={height} fill="white" />
              <path d={innerPath} fill="black" />
            </mask>
            
            {/* Limit liquid to inner bounds */}
            <clipPath id="liquid-clip">
              <path d={innerPath} />
            </clipPath>

            <filter id="drop-shadow" x="-20%" y="-20%" width="140%" height="140%">
              <feDropShadow dx="0" dy="15" stdDeviation="20" floodColor="#000" floodOpacity="0.25" />
            </filter>
          </defs>

          {/* Glass Body */}
          <path 
            d={outerPath} 
            fill={glassColor} 
            mask="url(#hollow-mask)" 
            filter="url(#drop-shadow)" 
          />

          {/* Liquid */}
          <g clipPath="url(#liquid-clip)">
            <rect
              x={cx - bulbRadius}
              y={currentLiquidY}
              width={bulbRadius * 2}
              height={height}
              fill={liquidColor}
            />
          </g>

          {/* 3D Specular Highlights */}
          <rect
            x={cx - tubeRx * 0.5}
            y={tubeTopY + tubeRx * 0.8}
            width={tubeRx * 0.3}
            height={intersectYOuter - tubeTopY - tubeRx}
            rx={tubeRx * 0.15}
            fill="#ffffff"
            opacity={0.3}
          />
          <circle
            cx={cx - bulbRadius * 0.35}
            cy={bulbCy - bulbRadius * 0.35}
            r={bulbRadius * 0.2}
            fill="#ffffff"
            opacity={0.3}
          />

          {/* Scale Marks */}
          {marks}
        </svg>

        {/* Value Text */}
        <div
          style={{
            position: "absolute",
            left: textLeft,
            top: 0,
            height: height,
            display: "flex",
            alignItems: "center",
            justifyContent: "flex-start",
            color: textColor,
            fontFamily,
            fontSize: height * 0.28,
            fontWeight: 700,
            fontVariantNumeric: "tabular-nums",
            lineHeight: 1,
            textShadow: "0px 10px 30px rgba(0,0,0,0.3)",
          }}
        >
          {displayValue}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default Thermometer;